package com.astratv.app;

import android.app.*;
import android.os.*;
import android.content.*;
import android.content.pm.ResolveInfo;
import android.graphics.*;
import android.graphics.drawable.*;
import android.view.*;
import android.widget.*;
import java.util.*;
import java.io.*;

public class MainActivity extends Activity {
    private LinearLayout root,body; private String page="Discover"; private android.content.SharedPreferences prefs;
    private final int ink=Color.rgb(8,13,24),muted=Color.rgb(158,174,197),white=Color.rgb(240,245,255);
    int dp(float x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
    @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("astra",0);show("Discover");}
    @Override protected void onResume(){super.onResume();if(root!=null)show(page);}
    TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(3),0,dp(3));return t;}
    LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    GradientDrawable shape(int color,int stroke){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(15));if(stroke!=0)d.setStroke(dp(2),stroke);return d;}
    void focus(View v){v.setFocusable(true);v.setOnFocusChangeListener((w,f)->{w.animate().scaleX(f?1.035f:1).scaleY(f?1.035f:1).setDuration(150).start();w.setBackground(shape(f?0xff253e5d:0xff142033,f?0xffb9d5ff:0));});v.setBackground(shape(0xff142033,0));}
    Button button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setTextColor(white);b.setTextSize(14);b.setAllCaps(false);b.setPadding(dp(18),dp(8),dp(18),dp(8));focus(b);b.setOnClickListener(v->action.run());return b;}
    void gap(LinearLayout l,int height){Space s=new Space(this);l.addView(s,new LinearLayout.LayoutParams(1,dp(height)));}
    void show(String selected){page=selected;root=column();root.setPadding(dp(38),dp(22),dp(38),dp(12));root.setBackgroundColor(ink);setContentView(root);
        LinearLayout nav=new LinearLayout(this);nav.setGravity(Gravity.CENTER_VERTICAL);TextView logo=text("✦  A S T R A",20,white);logo.setTypeface(null,Typeface.BOLD);nav.addView(logo,new LinearLayout.LayoutParams(0,dp(48),1));
        for(String n:new String[]{"Discover","Search","Watchlist","Add-ons","Settings"}){Button b=button(n,()->show(n));if(n.equals(page))b.setTextColor(0xffb9d5ff);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,dp(44));p.setMargins(dp(5),0,0,0);nav.addView(b,p);}root.addView(nav);gap(root,20);
        ScrollView scroll=new ScrollView(this);scroll.setClipToPadding(false);body=column();body.setPadding(dp(5),dp(5),dp(5),dp(15));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        switch(page){case "Add-ons":addons();break;case "Watchlist":watchlist();break;case "Settings":settings();break;case "Search":search();break;default:discover();}
    }
    void heading(String title,String subtitle){body.addView(text(title,29,white));body.addView(text(subtitle,13,muted));gap(body,14);}
    void discover(){
        LinearLayout hero=new LinearLayout(this);hero.setPadding(dp(24),dp(18),dp(20),dp(18));hero.setBackground(new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xff243d54,0xff141d33,0xff35283c}));
        LinearLayout copy=column();copy.addView(text("A S T R A   S P O T L I G H T",11,0xffb9d5ff));gap(copy,10);TextView name=text("A little wonder.\nA bigger adventure.",34,white);name.setTypeface(null,Typeface.BOLD);copy.addView(name);copy.addView(text("Big Buck Bunny  •  2008  •  Animation",13,0xffd0dceb));copy.addView(text("Settle into something extraordinary.",14,muted));gap(copy,14);copy.addView(button("▶  Explore film",()->details(Library.titles(this).get(0))));hero.addView(copy,new LinearLayout.LayoutParams(0,-2,3));hero.addView(new OrbitArt(this),new LinearLayout.LayoutParams(0,dp(234),2));body.addView(hero);gap(body,22);
        body.addView(text("Your next watch",21,white));titleRow(Library.titles(this));
        java.util.List<Library.Title> history=new ArrayList<>();for(Library.Title t:Library.titles(this))if(prefs.getInt("position."+t.id,0)>0)history.add(t);
        if(!history.isEmpty()){gap(body,15);body.addView(text("Continue watching",21,white));titleRow(history);}
        gap(body,20);body.addView(text("A world of add-ons",21,white));addonRow();
    }
    void titleRow(java.util.List<Library.Title> titles){HorizontalScrollView s=new HorizontalScrollView(this);s.setClipChildren(false);LinearLayout row=new LinearLayout(this);row.setPadding(dp(6),dp(9),dp(10),dp(9));for(Library.Title t:titles){LinearLayout card=column();card.setPadding(dp(16),dp(15),dp(16),dp(12));focus(card);card.addView(text("◈   "+t.genre.toUpperCase(Locale.ROOT),10,0xffb9d5ff));gap(card,18);TextView label=text(t.name,19,white);label.setTypeface(null,Typeface.BOLD);card.addView(label);card.addView(text(t.year+"  •  "+(prefs.getInt("position."+t.id,0)>0?"Resume available":"Details & playback"),11,muted));card.setOnClickListener(v->details(t));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(245),dp(132));p.setMargins(0,0,dp(14),0);row.addView(card,p);}s.addView(row);body.addView(s);}
    void details(Library.Title t){LinearLayout l=column();l.setPadding(dp(24),dp(10),dp(24),dp(10));l.addView(text(t.year+"  •  "+t.genre,13,muted));l.addView(text(t.description,17,white));gap(l,12);l.addView(text("Cast & creators",18,white));l.addView(text(t.cast,14,muted));gap(l,12);l.addView(text("Your review · saved on this device",18,white));EditText review=new EditText(this);review.setTextColor(white);review.setTextSize(15);review.setHintTextColor(muted);review.setHint("What did you think?");review.setText(prefs.getString("review."+t.id,""));l.addView(review);Button save=button("Save review",()->{prefs.edit().putString("review."+t.id,review.getText().toString()).apply();toast("Review saved");});l.addView(save);
        ScrollView sc=new ScrollView(this);sc.addView(l);new AlertDialog.Builder(this).setTitle(t.name).setView(sc).setPositiveButton(prefs.getInt("position."+t.id,0)>0?"Resume":"Play",(d,w)->startActivity(new Intent(this,PlayerActivity.class).putExtra("id",t.id).putExtra("title",t.name).putExtra("url",t.url))).setNeutralButton(prefs.getBoolean("saved."+t.id,false)?"Remove from watchlist":"Add to watchlist",(d,w)->{prefs.edit().putBoolean("saved."+t.id,!prefs.getBoolean("saved."+t.id,false)).apply();show(page);}).setNegativeButton("Close",null).show();
    }
    void watchlist(){heading("Watchlist","A place for everything you want to see.");java.util.List<Library.Title> saved=new ArrayList<>();for(Library.Title t:Library.titles(this))if(prefs.getBoolean("saved."+t.id,false))saved.add(t);if(saved.isEmpty())body.addView(text("Your watchlist is empty. Open a film and choose Add to watchlist.",17,muted));else titleRow(saved);}
    void search(){heading("Find your next favorite","Search the sample and your imported catalog.");EditText input=new EditText(this);input.setSingleLine(true);input.setTextColor(white);input.setHintTextColor(muted);input.setHint("Search titles, cast or genre");body.addView(input);LinearLayout results=column();body.addView(results);input.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int st,int before,int count){results.removeAllViews();String q=s.toString().toLowerCase(Locale.ROOT);int found=0;for(Library.Title t:Library.titles(MainActivity.this))if((t.name+" "+t.cast+" "+t.genre).toLowerCase(Locale.ROOT).contains(q)){results.addView(button(t.name,()->details(t)));found++;}if(found==0)results.addView(text("No titles found",16,muted));}public void afterTextChanged(android.text.Editable e){}});input.setText("");}
    void addons(){heading("Make room for more","Website companions, installed apps and your own media.");addonRow();gap(body,15);body.addView(text("Website playback stays with its provider. Pop-up windows are blocked; some providers require new windows, login or an external player. Cast, reviews and background play here apply to native catalog videos.",14,muted));gap(body,12);for(Library.Addon a:Library.addons())body.addView(button((prefs.getBoolean("addon."+a.id,true)?"✓ Enabled  ·  ":"Disabled  ·  ")+a.name,()->{prefs.edit().putBoolean("addon."+a.id,!prefs.getBoolean("addon."+a.id,true)).apply();show(page);}));}
    void addonRow(){HorizontalScrollView sc=new HorizontalScrollView(this);LinearLayout row=new LinearLayout(this);row.setPadding(dp(5),dp(8),dp(10),dp(8));for(Library.Addon a:Library.addons()){if(!prefs.getBoolean("addon."+a.id,true))continue;LinearLayout c=column();c.setPadding(dp(16),dp(13),dp(16),dp(13));focus(c);c.addView(text(a.id.equals("news")?"●  LIVE":"✦  ADD-ON",10,0xffa9c9ee));gap(c,7);c.addView(text(a.name,18,white));c.addView(text(a.description,11,muted));c.setOnClickListener(v->{if(a.id.equals("news"))news();else if(a.id.equals("netmirror"))netmirror(a);else web(a.name,a.url);});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(220),dp(120));p.setMargins(0,0,dp(12),0);row.addView(c,p);}sc.addView(row);body.addView(sc);}
    void web(String title,String url){startActivity(new Intent(this,WebAddonActivity.class).putExtra("title",title).putExtra("url",url));}
    void news(){String[] names={"TV9 Telugu","NTV Telugu","ETV channels","Sakshi TV"};String[] urls={"https://tv9telugu.com/live-tv","https://ntvtelugu.com/live-tv","https://www.etv.co.in/channels/","https://cms.sakshi.com/video/live"};new AlertDialog.Builder(this).setTitle("Telugu News · official pages").setItems(names,(d,w)->web(names[w],urls[w])).setNegativeButton("Close",null).show();}
    void netmirror(Library.Addon a){String pkg=prefs.getString("netmirror.package","");if(!pkg.isEmpty()){Intent launch=getPackageManager().getLeanbackLaunchIntentForPackage(pkg);if(launch==null)launch=getPackageManager().getLaunchIntentForPackage(pkg);if(launch!=null){startActivity(launch);return;}toast("Configured app is not installed");}new AlertDialog.Builder(this).setTitle("NetMirror companion").setMessage("Choose an installed NetMirror TV app in Settings, or open its website. Its APK runs separately and controls its own features and advertising.").setPositiveButton("Open website",(d,w)->web(a.name,a.url)).setNeutralButton("Choose installed app",(d,w)->chooseApp()).setNegativeButton("Close",null).show();}
    void chooseApp(){Intent q=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LEANBACK_LAUNCHER);java.util.List<ResolveInfo> apps=getPackageManager().queryIntentActivities(q,0);java.util.List<ResolveInfo> filtered=new ArrayList<>();for(ResolveInfo r:apps)if(!r.activityInfo.packageName.equals(getPackageName()))filtered.add(r);if(filtered.isEmpty()){toast("Install the NetMirror TV APK separately, then return here");return;}String[] names=new String[filtered.size()];for(int i=0;i<names.length;i++)names[i]=filtered.get(i).loadLabel(getPackageManager())+" · "+filtered.get(i).activityInfo.packageName;new AlertDialog.Builder(this).setTitle("Select your installed NetMirror app").setItems(names,(d,w)->{prefs.edit().putString("netmirror.package",filtered.get(w).activityInfo.packageName).apply();toast("Companion app linked");}).show();}
    void settings(){heading("Your space. Your way.","Astra TV · experimental build 0.1.0");body.addView(button("Import media catalog (JSON)",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,20);}));gap(body,10);body.addView(button("Choose installed NetMirror TV app",this::chooseApp));gap(body,10);body.addView(button("Background audio: "+(prefs.getBoolean("background",false)?"On":"Off"),()->{prefs.edit().putBoolean("background",!prefs.getBoolean("background",false)).apply();show(page);}));gap(body,10);body.addView(button("Stop background playback",()->{stopService(new Intent(this,PlaybackService.class));toast("Playback stopped");}));gap(body,10);body.addView(button("Clear watch history",()->{android.content.SharedPreferences.Editor e=prefs.edit();for(String k:prefs.getAll().keySet())if(k.startsWith("position."))e.remove(k);e.apply();toast("History cleared");}));gap(body,20);body.addView(text("Direct media supports HTTPS MP4 and device-supported HLS. Import only media you have permission to access. Website add-ons do not supply catalog metadata. No analytics or advertising SDKs are included.",14,muted));}
    @Override public void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req!=20||result!=RESULT_OK||data==null)return;try(InputStream in=getContentResolver().openInputStream(data.getData());ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>1048576)throw new IOException("Catalog must be under 1 MB");}String json=out.toString("UTF-8");int count=Library.parse(json).size();prefs.edit().putString("catalog",json).apply();toast("Imported "+count+" titles");}catch(Exception e){new AlertDialog.Builder(this).setTitle("Import failed").setMessage(e.getMessage()).setPositiveButton("OK",null).show();}}
    void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
    @Override public void onBackPressed(){if(!page.equals("Discover"))show("Discover");else super.onBackPressed();}
    static class OrbitArt extends View {Paint p=new Paint(3);OrbitArt(Context c){super(c);setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);}@Override protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();p.setShader(new RadialGradient(w*.55f,h*.5f,h*.46f,new int[]{0xffd2dcc8,0xff6b9b9a,0xff274750},null,Shader.TileMode.CLAMP));c.drawCircle(w*.55f,h*.5f,h*.36f,p);p.setShader(null);p.setColor(0x338ac8d8);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2);c.save();c.rotate(-25,w*.55f,h*.5f);c.drawOval(w*.06f,h*.28f,w*.99f,h*.72f,p);c.restore();p.setStyle(Paint.Style.FILL);p.setColor(0xffd5e6e4);for(int i=0;i<19;i++){float x=(i*97%997)/997f*w,y=(i*173%983)/983f*h;c.drawCircle(x,y,i%3+1,p);} }}
}
